@PedigreeBlock.reachable_of_restrict : ∀ {n B D : ℕ} (hBD : B ≤ D) (x : PedigreeBlock.Config n D) {a b : Fin (n + 1)},
  Relation.ReflTransGen (PedigreeBlock.Share (PedigreeBlock.restrictBlocks hBD x)) a b →
    Relation.ReflTransGen (PedigreeBlock.Share x) a b

@PedigreeBlock.uniform_pi_event : ∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] {α : ι → Type u_2}
  [inst_2 : (i : ι) → Fintype (α i)] [inst_3 : ∀ (i : ι), Nonempty (α i)] [inst_4 : (i : ι) → MeasurableSpace (α i)]
  [∀ (i : ι), MeasurableSingletonClass (α i)] (p : (i : ι) → α i → Prop),
  (PMF.uniformOfFintype ((i : ι) → α i)).toMeasure {x | ∀ (i : ι), p i (x i)} =
    ∏ i, (PMF.uniformOfFintype (α i)).toMeasure {a | p i a}

PedigreeBlock.config_bit_cylinder : ∀ (n B : ℕ) (p : Fin (n + 1) → Fin B → Bool → Prop),
  (PedigreeBlock.configLaw n B) {x | ∀ (i : Fin (n + 1)) (b : Fin B), p i b (x i b)} =
    ∏ i, ∏ b, (PMF.uniformOfFintype Bool).toMeasure {a | p i b a}

@PedigreeBlock.family_event_product : ∀ {ι : Type u_1} [inst : Fintype ι] (n : ι → ℕ) (B : ℕ)
  (p : (i : ι) → PedigreeBlock.Config (n i) B → Prop),
  (PedigreeBlock.familyLaw n B) {x | ∀ (i : ι), p i (x i)} = ∏ i, (PedigreeBlock.configLaw (n i) B) {x | p i x}

@PedigreeBlock.families_good_probability : ∀ {ι : Type u_1} [inst : Fintype ι] (n : ι → ℕ) (B : ℕ),
  0 < B →
    (PedigreeBlock.familyLaw n B) {x | ∀ (i : ι), ¬PedigreeBlock.Bad (x i)} = ∏ i, (1 - ↑(2 ^ n i - 1) / 2 ^ (B * n i))

@PedigreeBlock.observedShare_iff : ∀ {Child : Type u_1} {Family : Type u_2} {Symbol : Type u_3} {B : ℕ}
  (family : Child → Family) (choices : Child → PedigreeBlock.Code B) (symbols : Fin B → Family × Bool → Symbol),
  (∀ (j : Fin B), Function.Injective (symbols j)) →
    ∀ (a b : Child),
      PedigreeBlock.ObservedShare (PedigreeBlock.display family choices symbols) a b ↔
        a ≠ b ∧ family a = family b ∧ ∃ j, choices a j = choices b j

@PedigreeBlock.observed_path_preserves_family : ∀ {Child : Type u_1} {Family : Type u_2} {Symbol : Type u_3} {B : ℕ}
  (family : Child → Family) (choices : Child → PedigreeBlock.Code B) (symbols : Fin B → Family × Bool → Symbol),
  (∀ (j : Fin B), Function.Injective (symbols j)) →
    ∀ {a b : Child},
      Relation.ReflTransGen (PedigreeBlock.ObservedShare (PedigreeBlock.display family choices symbols)) a b →
        family a = family b

@PedigreeBlock.family_path_iff : ∀ {Family : Type u_1} {Symbol : Type u_2} {B : ℕ} {n : Family → ℕ}
  (x : (f : Family) → PedigreeBlock.Config (n f) B) (symbols : Fin B → Family × Bool → Symbol),
  (∀ (j : Fin B), Function.Injective (symbols j)) →
    ∀ (f : Family) (a b : Fin (n f + 1)),
      Relation.ReflTransGen (PedigreeBlock.ObservedShare (PedigreeBlock.familyObservations x symbols)) ⟨f, a⟩ ⟨f, b⟩ ↔
        Relation.ReflTransGen (PedigreeBlock.Share (x f)) a b

@PedigreeBlock.recovered_iff_connected : ∀ {Family : Type u_1} {Symbol : Type u_2} {B : ℕ} {n : Family → ℕ}
  (x : (f : Family) → PedigreeBlock.Config (n f) B) (symbols : Fin B → Family × Bool → Symbol),
  (∀ (j : Fin B), Function.Injective (symbols j)) →
    (PedigreeBlock.Recovered x symbols ↔ ∀ (f : Family), PedigreeBlock.Connected (x f))

@PedigreeBlock.observationLaw_probability : ∀ {Family : Type u_1} [inst : Fintype Family] {Symbol : Type u_2}
  [inst_1 : Fintype Symbol] [inst_2 : MeasurableSpace Symbol] [inst_3 : MeasurableSingletonClass Symbol]
  (n : Family → ℕ) (B : ℕ) (symbols : Fin B → Family × Bool → Symbol),
  MeasureTheory.IsProbabilityMeasure (PedigreeBlock.observationLaw n B symbols)

@Claims.BlockRecovery.recovered_of_restrict : ∀ {Family : Type u_1} {Symbol : Type u_2} {n : Family → ℕ} {B D : ℕ}
  (hBD : B ≤ D) (x : (i : Family) → PedigreeBlock.Config (n i) D) (symbols : Fin D → Family × Bool → Symbol),
  (∀ (j : Fin D), Function.Injective (symbols j)) →
    (PedigreeBlock.Recovered (fun i => PedigreeBlock.restrictBlocks hBD (x i)) fun j => symbols (Fin.castLE hBD j)) →
      PedigreeBlock.Recovered x symbols
